import React from 'react';
import Card from '../../components/Card';

const AdminDashboard = () => {
  return (
    <div className="p-6">
      <h1 className="text-3xl font-bold mb-6">Admin Dashboard</h1>
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <Card>
          <h3 className="text-xl font-semibold mb-2">Doctors</h3>
          <p className="text-gray-600">Manage doctors and their profiles</p>
        </Card>
        <Card>
          <h3 className="text-xl font-semibold mb-2">Receptionists</h3>
          <p className="text-gray-600">Manage receptionist accounts</p>
        </Card>
        <Card>
          <h3 className="text-xl font-semibold mb-2">System</h3>
          <p className="text-gray-600">System overview and settings</p>
        </Card>
      </div>
    </div>
  );
};

export default AdminDashboard;
